def position_after(route, steps):
    move = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}
    x = y = 0
    for k in range(steps):
        dx, dy = move[route[k % len(route)]]
        x += dx
        y += dy
    return [x, y]
